import React, { useEffect, useState } from 'react';
import api from '../utils/api';

const Table = ({ tableName, items }) => {
    // Only take the first 5 entries
    const limitedItems = items.slice(0, 5);

    return (
        <div>
            <h2>{tableName}</h2>
            <table>
                <thead>
                    <tr>
                        {limitedItems[0] && Object.keys(limitedItems[0]).map(key => (
                            <th key={key}>{key}</th>
                        ))}
                    </tr>
                </thead>
                <tbody>
                    {limitedItems.map((item, index) => (
                        <tr key={index}>
                            {Object.values(item).map((value, idx) => (
                                <td key={idx}>{value}</td>
                            ))}
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    );
};

const ChartComponent = () => {
    const [data, setData] = useState({});
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const result = await api.getData();
                console.log('Data received:', result.data); // Log the data received
                setData(result.data);
            } catch (error) {
                console.error('Error fetching data:', error);
                setError('Error fetching data.');
            }
        };

        fetchData();
    }, []);

    if (error) {
        return <div>{error}</div>;
    }

    // Checking if data object is not empty
    const dataEntries = Object.entries(data);

    return (
        <div>
            <h1>DynamoDB Data</h1>
            {dataEntries.length === 0 ? (
                <p>No data available.</p>
            ) : (
                dataEntries.map(([tableName, items]) => (
                    <Table key={tableName} tableName={tableName} items={items} />
                ))
            )}
        </div>
    );
};

export default ChartComponent;
